function validate([text]) {
  if (typeof text !== 'string' || text.length < 1 || text.length > 100000) return 'text needs 1 to 100000 characters.';
  for (let i = 0; i < text.length; i++) if (text.charCodeAt(i) > 255) return 'text may only use the 256 ASCII characters.';
  return null;
}

