function entityParser(text) {
  const symbols = new Map([
    ['&quot;', '"'],
    ['&apos;', "'"],
    ['&amp;', '&'],
    ['&gt;', '>'],
    ['&lt;', '<'],
    ['&frasl;', '/'],
  ]);
  const result = [];
  let i = 0;
  while (i < text.length) {
    if (text[i] === '&') {
      const chunk = text.slice(i, i + 7);
      const semicolon = chunk.indexOf(';');
      const entity = chunk.slice(0, semicolon + 1);
      if (semicolon !== -1 && symbols.has(entity)) {
        result.push(symbols.get(entity));
        i += entity.length;
        continue;
      }
    }
    result.push(text[i]);
    i++;
  }
  return result.join('');
}

brute:
function entityParser(text) {
  const decode = { quot: '"', apos: "'", amp: '&', gt: '>', lt: '<', frasl: '/' };
  return text.replace(/&(quot|apos|amp|gt|lt|frasl);/g, (match, name) => decode[name]);
}

