function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const pieces = ['&quot;', '&apos;', '&amp;', '&gt;', '&lt;', '&frasl;', '&', ';', '&&', 'amp;', 'gt;', '&amp', '&lt', '&frasl', '&fras;', '&ambassador;', '&GT;', '&Amp;', '&;', 'a', 'b', 'x', ' ', '"', "'", '<', '>', '/', '.', 'html', '1'];
  const limit = size === 'large' ? 9000 + Math.floor(rand() * 900) : 1 + Math.floor(rand() * 24);
  let text = '';
  while (text.length < limit) text += pick(pieces);
  return [text];
}
